import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"ioBroker : attribution automatique des rôles","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/mqtt-client/iobroker-roles.md","filePath":"fr/projects/mqtt-client/iobroker-roles.md","lastUpdated":1794513612000}'),r={name:"fr/projects/mqtt-client/iobroker-roles.md"};function n(i,e,d,c,l,u){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="iobroker-role-mapping" tabindex="-1">ioBroker : attribution automatique des rôles <a class="header-anchor" href="#iobroker-role-mapping" aria-label="Permalink to &quot;ioBroker : attribution automatique des rôles {#iobroker-role-mapping}&quot;">​</a></h1><p>Le JavaScript optionnel est fourni avec MQTT-Client <strong>0.1.34</strong> et s’exécute dans l’adaptateur JavaScript d’ioBroker. Il exploite les métadonnées transmises <code>device_class</code> et <code>unit_of_measurement</code>. Seuls les cas non ambigus sont traités ; les valeurs MQTT, types, unités, identifiants de connexion et canaux de commande ne sont pas réécrits.</p><h2 id="settings-persistence-0136" tabindex="-1">Nouveauté 0.1.36 : conserver les réglages après les mises à jour <a class="header-anchor" href="#settings-persistence-0136" aria-label="Permalink to &quot;Nouveauté 0.1.36 : conserver les réglages après les mises à jour {#settings-persistence-0136}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Test de redémarrage réussi le 7 novembre 2026</p><p>Après avoir de nouveau enregistré les réglages lors du passage à <strong>0.1.36</strong>, l’utilisateur a redémarré l’application MQTT-Client et confirmé : <strong>La case des mesures associées reste cochée et la structure MQTT reste « Plate avec noms courts ».</strong> Le test pratique de redémarrage est donc réussi. Aucun nouveau changement de version n’a été testé ; le test pratique de mise à jour vers la prochaine version reste à effectuer.</p></div><p><strong>Les réglages enregistrés dans l’application sont désormais conservés lorsque le Supervisor Home Assistant régénère son fichier d’options pendant une mise à jour.</strong> Cela concerne notamment la case des mesures associées, la structure MQTT des nouvelles entités, les autres réglages enregistrés et les identifiants de connexion. L’application les conserve séparément dans son fichier privé <code>/data/mqtt-settings.json</code>. Les affectations de chemins MQTT restent dans <code>/data/mqtt-routes.json</code> ; les points et références VIS-2 existants ne changent pas.</p><p><strong>Premier passage depuis la version 0.1.35 ou antérieure :</strong> Exportez les réglages dans l’application avant la mise à jour. S’ils ont déjà été réinitialisés lors de ce premier passage, importez ensuite la sauvegarde ou sélectionnez de nouveau les deux options une fois, puis cliquez sur <strong>Enregistrer et connecter</strong>. Les réglages déjà perdus ne peuvent pas être reconstitués de façon fiable ; les mesures supplémentaires ne sont jamais activées sans votre choix.</p><p>Modifiez de préférence ces réglages dans l’application. Les modifications réelles de la configuration Supervisor sont reprises au redémarrage ; ses valeurs par défaut inchangées ne réinitialisent pas les choix de l’application. Pour revenir explicitement à un choix par défaut, sélectionnez-le et enregistrez-le dans l’application. Les sauvegardes de réglages existantes restent utilisables et excluent toujours les mots de passe et clés TLS privées. Le script JavaScript reste en version <strong>0.1.34</strong> ; ce correctif ne nécessite pas de le remplacer à nouveau.</p><p>Contexte : le Supervisor gère <code>/data/options.json</code> ; le répertoire privé <code>/data</code> fournit le stockage persistant de l’application. <a href="https://contributors.home-assistant.io/apps/reference/environment/" target="_blank" rel="noreferrer">Documentation officielle HA</a>.</p><h2 id="mqtt-layout-0134" tabindex="-1">Nouveauté 0.1.34 : chemins MQTT plats pour les nouvelles entités uniquement <a class="header-anchor" href="#mqtt-layout-0134" aria-label="Permalink to &quot;Nouveauté 0.1.34 : chemins MQTT plats pour les nouvelles entités uniquement {#mqtt-layout-0134}&quot;">​</a></h2><p>Dans <strong>Transmission et TLS → Structure MQTT des nouvelles entités</strong>, choisissez <strong>Plate avec noms courts</strong>, puis <strong>Enregistrer et connecter</strong>. La structure existante reste le choix par défaut. Ce réglage concerne les entités manuelles et les membres d’un label rencontrés pour la première fois ensuite, y compris les mesures facultatives du même appareil.</p><p>Les entités connues conservent leurs chemins. Les affectations sont enregistrées durablement dans <code>/data/mqtt-routes.json</code> et incluses dans la sauvegarde exportée des réglages. Retirer puis resélectionner un label, renommer, redémarrer ou mettre à jour réutilise le chemin attribué. Lors de la première mise à jour, les sélections existantes et les topics enregistrés sont conservés ; la sélection existante du label est fixée au premier rapprochement réussi. Ne supprimez pas ce fichier. Revenir au réglage précédent ne migre pas les entités déjà affectées.</p><p>Exemples de nouveaux topics MQTT plats :</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ha_external/geraet/schalter</span></span>
<span class="line"><span>ha_external/geraet/schalter_set</span></span>
<span class="line"><span>ha_external/geraet/schalter_attribute/device_class</span></span>
<span class="line"><span>ha_external/geraet/energie</span></span>
<span class="line"><span>ha_external/geraet/leistung</span></span>
<span class="line"><span>ha_external/geraet/licht_brightness</span></span>
<span class="line"><span>ha_external/geraet/licht_brightness_set</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Les anciens topics comme <code>ha_external/geraet/switch/state</code> et <code>…/switch/set</code> restent valides en parallèle. Les noms courts en conflit reçoivent un suffixe unique. Les points, valeurs, alias et références VIS-2 existants ne sont ni renommés ni supprimés.</p><p><strong>Avant d’activer les chemins MQTT plats, remplacez le script JavaScript complet par la version 0.1.34 en conservant vos réglages.</strong> Il lit les deux structures grâce au catalogue transmis, qui indique les chemins exacts des états et commandes. Vérifiez la prévisualisation, puis choisissez <code>mode: &#39;apply&#39;</code>. Les anciens scripts ne reconnaissent pas les nouveaux chemins MQTT plats. L’option indépendante du script <code>virtualLayout: &#39;flat&#39;</code> détermine uniquement la présentation sous <code>0_userdata.0.ugso_mqtt</code>. Les rôles manuels et références existants restent protégés.</p><h2 id="enable-device-readings" tabindex="-1">Important : activer explicitement les mesures supplémentaires <a class="header-anchor" href="#enable-device-readings" aria-label="Permalink to &quot;Important : activer explicitement les mesures supplémentaires {#enable-device-readings}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Important : activer explicitement les mesures supplémentaires</p><p><strong>Une étiquette seule n’active pas les mesures supplémentaires.</strong> Dans <strong>Transmission et TLS</strong>, cochez <strong>« Inclure automatiquement les mesures et valeurs de batterie du même appareil »</strong> (interface allemande : <strong>„Zugehörige Mess- und Batteriewerte desselben Geräts automatisch einbeziehen“</strong>), puis cliquez sur <strong>« Enregistrer et connecter »</strong>. Sans cette case, l’énergie, la tension, le courant et la puissance ne sont pas automatiquement ajoutés à l’interrupteur étiqueté. Les valeurs sélectionnées manuellement restent indépendantes de cette option.</p></div><p>Seuls les capteurs compatibles, activés dans HA et associés au même appareil HA sont inclus, s’ils existent. Aucune mesure absente de l’appareil n’est créée. <strong>« Vérifier les mesures associées »</strong> indique la détection et les motifs d’exclusion. Les états de commande sont prioritaires ; les mesures peuvent suivre avec un délai.</p><h2 id="javascript-vis2-helper" tabindex="-1">Pour VIS 2 en particulier : le script JavaScript ioBroker <a class="header-anchor" href="#javascript-vis2-helper" aria-label="Permalink to &quot;Pour VIS 2 en particulier : le script JavaScript ioBroker {#javascript-vis2-helper}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Pour VIS 2 en particulier : le script JavaScript ioBroker</p><p>Le <strong>JavaScript fourni s’exécute dans l’adaptateur JavaScript ioBroker, pas dans Home Assistant</strong>. Il crée des points virtuels sous <code>0_userdata.0.ugso_mqtt</code> : <strong>un point par valeur pour l’affichage et la commande</strong>, même si MQTT utilise des topics <code>state</code> et <code>set</code> séparés. Les interrupteurs et valeurs de lampe compatibles disposent du canal de commande approprié ; les mesures restent en lecture seule. Les métadonnées HA adaptées déterminent les types, unités et rôles non ambigus. Une commande n’est confirmée qu’après un véritable retour HA.</p><p><strong>Vérifiez d’abord l’aperçu, puis choisissez <code>mode: &#39;apply&#39;</code>.</strong> L’aperçu crée uniquement les dossiers de base/points de sauvegarde manquants du script ; les points VIS-2 virtuels sont créés en mode application. <strong>setObject</strong> doit être autorisé dans les réglages de l’adaptateur pour leur création. Les valeurs existantes et rôles définis manuellement restent protégés. L’application HA et le script sont en <strong>0.1.33</strong> pour cette fonction. Remplacez le script complet dans ioBroker pour la structure plate ; la mise à jour de l’application seule ne suffit pas. Le transfert MQTT seul fonctionne aussi sans le script.</p></div><h2 id="flat-layout-0133" tabindex="-1">Nouveauté 0.1.33 : structure VIS-2 plate avec noms courts <a class="header-anchor" href="#flat-layout-0133" aria-label="Permalink to &quot;Nouveauté 0.1.33 : structure VIS-2 plate avec noms courts {#flat-layout-0133}&quot;">​</a></h2><p><strong>Remplacez le script JavaScript complet par la version 0.1.33 en conservant vos réglages.</strong> Dans son bloc de réglages, <code>virtualLayout: &#39;nested&#39;</code> sélectionne la structure existante (par défaut) ; <code>virtualLayout: &#39;flat&#39;</code> crée des points courts directement sous le dossier de l’appareil, par exemple <code>schalter</code>, <code>energie</code>, <code>leistung</code>, <code>spannung</code>, <code>stromstaerke</code>. Les lampes ajoutent les valeurs compatibles comme <code>helligkeit</code>, <code>farbe</code>, <code>effekt</code> et <code>farbtemperatur</code>. Les noms identiques ou occupés reçoivent un suffixe unique comme <code>leistung_2</code> ; les affectations attribuées restent fixées dans le journal de sauvegarde.</p><p>Vérifiez d’abord l’aperçu, puis choisissez <code>mode: &#39;apply&#39;</code>. Le changement de structure ne supprime ni ne déplace aucun point existant. Les anciens et nouveaux identifiants déjà créés par le script restent actualisés et conservent leurs canaux de commande autorisés ; les références VIS-2 existantes peuvent rester. Les anciens dossiers restent donc visibles au départ. Les objets tiers et rôles manuels ne sont pas écrasés et les topics MQTT restent inchangés. Pour revenir en arrière, sélectionnez <code>nested</code> dans le nouveau script ; l’ancien script 0.1.27 ne peut pas lire les journaux contenant des entrées plates.</p><h2 id="readings-highlight-0132" tabindex="-1">Nouveauté 0.1.32 : mesures supplémentaires mises en évidence <a class="header-anchor" href="#readings-highlight-0132" aria-label="Permalink to &quot;Nouveauté 0.1.32 : mesures supplémentaires mises en évidence {#readings-highlight-0132}&quot;">​</a></h2><p>L’option <strong>« Inclure automatiquement les mesures et valeurs de batterie du même appareil »</strong> est mise en évidence en jaune. Cette présentation n’active pas la case : faites votre choix, puis cliquez sur <strong>« Enregistrer et connecter »</strong>. Les réglages existants sont conservés. TLS et certificats restent repliables séparément.</p><h2 id="tls-0131" tabindex="-1">Nouveauté 0.1.31 : TLS et certificats repliables séparément <a class="header-anchor" href="#tls-0131" aria-label="Permalink to &quot;Nouveauté 0.1.31 : TLS et certificats repliables séparément {#tls-0131}&quot;">​</a></h2><p><strong>TLS et certificats</strong> dispose désormais d’une section repliable indépendante, utilisable à la souris et au clavier. Son bouton indique si TLS est sélectionné, même une fois replié. L’ouverture ou la fermeture ne modifie ni TLS, ni les certificats enregistrés, ni les identifiants. La section reste repliée après chargement et enregistrement ; les réglages de transmission et les deux boutons d’action restent visibles. Le <a href="/fr/blog/snippets/iobroker-blockly#mqtt-vis2-helper">nouvel article sur le script JavaScript</a> explique l’objectif, l’installation, les états/commandes et les sauvegardes, avec le script 0.1.27 complet et inchangé, un bouton de copie et un téléchargement.</p><h2 id="credentials-0130" tabindex="-1">Nouveauté 0.1.30 : identifiants repliables <a class="header-anchor" href="#credentials-0130" aria-label="Permalink to &quot;Nouveauté 0.1.30 : identifiants repliables {#credentials-0130}&quot;">​</a></h2><p>La section <strong>Identifiants</strong> dispose désormais d’un bouton pour la déplier ou la replier, également utilisable au clavier. Si le broker est configuré, l’adresse IP, le port, le nom d’utilisateur et le mot de passe restent repliés après chargement et enregistrement. Si des champs obligatoires manquent, la section s’ouvre pour les corriger. <strong>Transmission et TLS</strong>, <strong>Enregistrer et connecter</strong> et <strong>Valeurs actuellement transmises</strong> restent visibles. Les réglages et identifiants ne sont pas modifiés. La priorité de la version 0.1.29 et le script 0.1.27 sont conservés. L’utilisateur a confirmé le bon fonctionnement du retour de commande avec un délai d’environ une demi-seconde. La lampe Zigbee a également été testée avec succès : le retour d’état fonctionne et la luminosité suit HA à 100 %.</p><h2 id="priority-0129" tabindex="-1">Nouveauté 0.1.29 : états de commande avant mesures <a class="header-anchor" href="#priority-0129" aria-label="Permalink to &quot;Nouveauté 0.1.29 : états de commande avant mesures {#priority-0129}&quot;">​</a></h2><p><strong>Mettez l’application HA MQTT-Client à jour vers 0.1.29 ; le script ioBroker 0.1.27 reste inchangé.</strong> Les états de commande/contact et les retours des commandes sont prioritaires sur les mesures et ne subissent pas la pause de publication configurée. Une transmission déjà engagée se termine normalement ; entre les messages, les lots de mesures/attributs cèdent la priorité aux états urgents ou commandes. À partir de 32 événements en attente, des lots limités de capteurs regroupent les valeurs intermédiaires pour conserver le dernier état de chaque source. Les changements de commande ordinaires restent conservés. Un contrôle périodique lit les états HA réels même avec la connexion en direct active, selon le <code>poll_interval</code> existant (5 secondes par défaut). Les valeurs inchangées ne sont pas republiées. <strong>Übertragung und TLS</strong> et la pause de publication des mesures/attributs sont directement visibles ; les identifiants de connexion restent repliables séparément. La ligne d’état distingue la file (<strong>Wartend</strong>), les événements regroupés (<strong>Zusammengefasst</strong>), la dernière réception HA (<strong>HA-Eingang</strong>) et le compteur cumulatif (<strong>Gesendet</strong>). Les réglages et valeurs existants sont conservés. Pour vérifier, laissez le contrôle à 5 secondes et actionnez un relais non critique dans HA. Seul un retour HA réel entraîne <code>ack: true</code> ; la transmission au broker ne suffit pas. Vérifié localement ; la latence réelle chez l’utilisateur reste à confirmer.</p><p>Les interrupteurs sont reconnus par le domaine <code>switch.*</code>, sans classe d’appareil ni unité obligatoire. Les lampes utilisent <code>light.*</code>. La sélection automatique des mesures, lorsqu’elle est activée, reste limitée au même appareil HA. Les capteurs utilisent d’abord <code>device_class</code> ; si elle manque, les unités non ambiguës de <code>unit_of_measurement</code>, telles que W/kW/MW, V/mV/kV, A/mA et Wh/kWh/MWh, sont utilisées. Les classes existantes ne sont jamais remplacées ; des noms similaires ou un pourcentage ambigu ne suffisent pas. <strong>Vérifier les mesures associées</strong> (interface allemande : <strong>Zugehörige Messwerte prüfen</strong>) affiche un rapport en lecture seule des capteurs détectés et des motifs d’exclusion : association d’appareil absente, entité désactivée ou classe/unité inadaptée. Les mesures peuvent attendre derrière les états de commande. Les réglages, identifiants et valeurs existantes sont conservés.</p><h2 id="live-0128" tabindex="-1">Nouveauté 0.1.28 : retours HA sans surcharge d’événements étrangers <a class="header-anchor" href="#live-0128" aria-label="Permalink to &quot;Nouveauté 0.1.28 : retours HA sans surcharge d’événements étrangers {#live-0128}&quot;">​</a></h2><p>Cette correction concerne <strong>l’application MQTT-Client dans Home Assistant</strong> : mettez-la à jour vers 0.1.28 et redémarrez l’application. Le script ioBroker 0.1.27 peut rester inchangé ; son seul remplacement ne corrige pas la réception des événements HA. Avec la sélection par étiquette, seuls les événements des entités sélectionnées et de leurs mesures du même appareil activées sont mis en file. Les événements du reste de HA ne peuvent plus remplir cette file. Après modification des étiquettes ou des affectations d’appareils, le client récupère des états HA récents. Les états en attente avec un ancien <code>last_updated</code> sont ignorés après resynchronisation ; les changements normalement ordonnés restent conservés. Le compteur de surcharge est cumulatif depuis le démarrage et signale toujours les débordements réels des événements sélectionnés. Le délai de publication configuré, les identifiants de connexion et les sélections sont conservés ; une première synchronisation importante peut encore durer. Après celle-ci, actionnez un relais non critique dans HA et vérifiez que MQTT et le point virtuel ioBroker suivent rapidement. La confirmation sur le système réel de l’utilisateur reste à faire.</p><h2 id="commands-0127" tabindex="-1">Nouveauté 0.1.27 : commandes sans retain <a class="header-anchor" href="#commands-0127" aria-label="Permalink to &quot;Nouveauté 0.1.27 : commandes sans retain {#commands-0127}&quot;">​</a></h2><p>Les commandes utilisent désormais l’API <code>sendMessage2Client</code> de l’adaptateur MQTT ioBroker avec <strong><code>retain: false</code></strong>. En mode serveur, une écriture normale dans un point MQTT <code>set</code> peut parvenir au client avec le drapeau RETAIN. Le client HA continue de refuser ces commandes afin de ne pas exécuter d’anciennes demandes à la reconnexion. Les réglages globaux du broker et les valeurs des points MQTT sont conservés. Le script vérifie le topic de commande par rapport au topic d’état via <code>native.topic</code>, sans déduire les chemins des identifiants d’objets. Dans VIS 2, commandez toujours le point virtuel sous <code>0_userdata.0.ugso_mqtt</code> avec <code>ack: false</code> et <code>mode: &#39;apply&#39;</code>. La ligne <code>Command handed to MQTT adapter (retain=false)</code> confirme uniquement la transmission à l’adaptateur ; un nouvel état HA doit confirmer l’exécution. La valeur brute du point MQTT <code>set</code> ne change pas nécessairement. Aucun nouvel essai automatique ; les erreurs ou l’absence de retour HA restent non confirmées. Remplacez le fichier complet du script en conservant vos réglages.</p><h2 id="setup-0126" tabindex="-1">Nouveauté 0.1.26 : création automatique de la base <a class="header-anchor" href="#setup-0126" aria-label="Permalink to &quot;Nouveauté 0.1.26 : création automatique de la base {#setup-0126}&quot;">​</a></h2><p>Les dossiers de base du script (<code>virtualRoot</code>, <code>aliasRoot</code>) et les deux points de sauvegarde (<code>virtualBackupId</code>, <code>backupId</code>) absents sont désormais créés automatiquement au démarrage dans <strong>tous les modes</strong>, y compris <code>preview</code> et <code>restore</code>. Les dossiers, sauvegardes, valeurs et rôles manuels existants ne sont pas écrasés. Les nouveaux journaux contiennent des structures vides valides. Autorisez <code>setObject</code> dans l’instance JavaScript même pour l’aperçu. Les autorisations manquantes et les chemins incompatibles sont signalés comme erreurs. L’aperçu ne crée aucun point VIS 2 commandable et ne modifie ni les rôles MQTT ni les valeurs des appareils ; utilisez <code>mode: &#39;apply&#39;</code> après vérification pour ces opérations. Le traitement événementiel de la version 0.1.25 est conservé.</p><h2 id="fix-0125" tabindex="-1">Correction 0.1.25 : objets absents sans avertissements <a class="header-anchor" href="#fix-0125" aria-label="Permalink to &quot;Correction 0.1.25 : objets absents sans avertissements {#fix-0125}&quot;">​</a></h2><p>L’adaptateur JavaScript <strong>10.4.10</strong> émet aussi un avertissement lorsque <code>getObject</code> lit un identifiant absent. Le script vérifie désormais <code>existsObject</code> et <code>existsState</code> avant toute lecture d’objet ou d’état : journal, métadonnées optionnelles, dossiers et points virtuels non encore créés. La protection précédente utilisant seulement <code>getObject</code> était insuffisante.</p><p>L’aperçu affiche des lignes <code>Preview VIS 2</code> mais crée uniquement les dossiers de base et sauvegardes absents. Après vérification, choisissez <code>mode: &#39;apply&#39;</code> pour la création automatique. Autorisez <code>setObject</code> dans l’instance JavaScript et désactivez <strong>Do not subscribe to all states on start</strong>, car le script lit les caches d’états de manière synchrone. Une création propre au script interrompue peut être retentée après correction des autorisations ; les points étrangers ou modifiés restent protégés.</p><p>MQTT-Client <strong>0.1.24 ou ultérieur</strong> fournit le catalogue requis ; remplacer le fichier complet du script suffit pour cette correction. Les anciens topics persistants désélectionnés sans identité d’entité actuelle sont ignorés. Les métadonnées HA absentes ne sont jamais inventées. Le message de démarrage indique maintenant version et mode.</p><p>Le script regroupe les changements MQTT réels pendant une seconde. Le mode virtuel traite uniquement les sources concernées ; les répétitions identiques et les attributs sans rapport ne déclenchent aucun passage. Une analyse complète a lieu au démarrage et lorsque le catalogue de sélection ou la disponibilité change. La vérification du délai concerne uniquement les commandes en attente et cesse après confirmation ou expiration. Chaque entité utilise uniquement le canal de commande correspondant à son état ; les objets ioBroker existants ne sont pas supprimés.</p><h2 id="vis2" tabindex="-1">Nouveauté 0.1.24 : un point VIS 2 pour l’état et la commande <a class="header-anchor" href="#vis2" aria-label="Permalink to &quot;Nouveauté 0.1.24 : un point VIS 2 pour l’état et la commande {#vis2}&quot;">​</a></h2><p>Le script crée désormais automatiquement des points virtuels et dossiers sous <code>0_userdata.0.ugso_mqtt</code>. Il cible les API de l’adaptateur JavaScript ioBroker <strong>10.4.10</strong>. Commencez par <strong>mettre MQTT-Client à jour vers 0.1.24</strong> et reconnectez-le : le nouveau catalogue associe chaque entité à son topic actuel et à son autorisation de commande. Les anciens topics persistants ne doivent pas créer de commandes en double.</p><p>Conservez d’abord ces paramètres en haut du script complet :</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">outputMode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;virtual&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;preview&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mqttRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;mqtt.0.ha_external&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualRoot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">virtualBackupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;0_userdata.0.ugso_mqtt_helper.backup&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Après vérification de l’aperçu, passez à <code>mode: &#39;apply&#39;</code> et redémarrez. <strong>Le point de sauvegarde, les dossiers et les nouveaux points VIS 2 sont créés automatiquement.</strong> L’aperçu crée uniquement les dossiers de base et sauvegardes absents ; les nouveaux points VIS 2 nécessitent <code>apply</code>. Les points étrangers existants, alias et rôles manuels ne sont pas écrasés. Votre ancien alias, par exemple sous <code>alias.0.HA</code>, peut être conservé.</p><p>Exemple : <code>mqtt.0.ha_external.claudia_pc.switch.state</code> et son canal <code>mqtt.0.ha_external.claudia_pc.switch.set</code> deviennent <code>0_userdata.0.ugso_mqtt.claudia_pc.switch.state</code>. <strong>Utilisez uniquement ce point virtuel dans VIS 2.</strong></p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Direction/fonction</th><th>Comportement</th></tr></thead><tbody><tr><td>Retour MQTT → VIS 2</td><td>État confirmé avec <code>ack: true</code></td></tr><tr><td>Action VIS 2 → commande MQTT</td><td>Seules les actions actuelles avec <code>ack: false</code> sont envoyées à <code>/set</code></td></tr><tr><td>Interrupteur</td><td>Normaliser virtuellement <code>on</code>/<code>off</code> en booléens ; renvoyer <code>ON</code>/<code>OFF</code></td></tr><tr><td>Luminosité</td><td>Pourcentage 0–100, limites vérifiées</td></tr><tr><td>RGB</td><td>Tableau JSON MQTT ↔ couleur hexadécimale virtuelle <code>#RRGGBB</code></td></tr><tr><td>Effet</td><td>Uniquement les choix de la liste d’effets actuelle</td></tr><tr><td>Température de couleur</td><td>Kelvin entiers dans les limites actuelles</td></tr><tr><td>Nombres, listes et texte</td><td>Vérifier les limites ou choix disponibles</td></tr><tr><td>Dates, mesures et batterie</td><td>Lecture seule ; valeurs MQTT d’origine conservées</td></tr></tbody></table></div><p>La création, le démarrage et le redémarrage n’envoient aucune commande et ne rejouent jamais d’anciennes actions. Un nouveau retour HA confirme la valeur ; l’acceptation par le broker ne confirme pas l’exécution. Sans nouveau retour pendant environ 30 secondes, la demande reste non confirmée avec la qualité d’erreur <code>q: 128</code>. Si la source est désélectionnée, inconnue ou hors ligne, la dernière valeur est conservée avec <code>q: 130</code> et les commandes sont bloquées. Aucune valeur zéro ou arrêt n’est inventée.</p><p>Le journal <code>virtualBackupId</code> est enregistré et vérifié avant chaque création. Il contient les associations et définitions d’objets, sans identifiants MQTT ni mesures actuelles. Le mode virtuel ne modifie pas les objets MQTT d’origine. Avec <code>mode: &#39;restore&#39;</code>, les valeurs virtuelles et références du tableau de bord sont conservées ; les commandes virtuelles propres au script passent en lecture seule et la synchronisation s’arrête. Arrêtez ensuite le script.</p><p>La fonction précédente reste accessible avec <code>outputMode: &#39;roles&#39;</code>. Les règles de rôles directs/alias et leur restauration ci-dessous concernent ce mode ; les tableaux décrivent aussi la signification des points virtuels. <strong>N’exécutez qu’une seule copie du script à la fois.</strong> Les attributs optionnels absents et le journal non encore créé ne produisent plus les anciens avertissements <code>getState</code>.</p><h2 id="installation" tabindex="-1">Installation et sauvegarde <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation et sauvegarde {#installation}&quot;">​</a></h2><ol><li>Exportez d’abord dans ioBroker Admin les objets MQTT concernés avec leurs états et les scripts existants, ou effectuez une sauvegarde complète.</li><li>Dans MQTT-Client, choisissez <strong>ioBroker-/VIS-2-Helfer herunterladen</strong>, ou <a href="https://raw.githubusercontent.com/rockbaer2007/ugso-ha-mqtt-addons/master/mqtt_client/app/iobroker/ugso-mqtt-role-mapper.js" target="_blank" rel="noreferrer">téléchargez le script</a>.</li><li>Dans <strong>Scripts</strong> d’ioBroker, créez un <strong>JavaScript</strong> et collez le fichier entier. Une seule copie doit fonctionner dans une seule instance JavaScript.</li><li>Réglez <code>mqttRoot</code> sur votre chemin MQTT, par exemple <code>mqtt.0.ha_external</code>. Les caractères génériques sont interdits.</li><li>Conservez <code>mode: &#39;preview&#39;</code>, démarrez le script et consultez son journal. L’aperçu crée uniquement les dossiers de base et sauvegardes absents.</li><li>Ajoutez dans <code>excludeIds</code> les points auxquels vous avez attribué manuellement le rôle générique <code>state</code>. Ce rôle manuel est indiscernable du rôle par défaut.</li><li>Après vérification, passez à <code>mode: &#39;apply&#39;</code> et redémarrez le script. Autorisez <code>setObject</code> dans les paramètres de l’instance JavaScript. Celle-ci doit pouvoir lire les états MQTT.</li></ol><p>Avant chaque modification, le rôle initial est enregistré dans l’état JSON <code>0_userdata.0.ugso_mqtt_roles.backup</code>, puis la sauvegarde est vérifiée. Le journal ne contient ni relevés de compteur ni identifiants de connexion. Un échec de sauvegarde bloque la modification suivante. Exportez également cet état de sauvegarde et conservez-le.</p><p>Les rôles spécifiques tels que <code>date</code>, <code>text</code> ou <code>value.temperature</code> ne sont pas remplacés. Une modification manuelle ultérieure empêche une nouvelle attribution automatique au même point. Aucun alias existant n’est écrasé.</p><h2 id="aliases" tabindex="-1">Rôles directs et alias en lecture seule <a class="header-anchor" href="#aliases" aria-label="Permalink to &quot;Rôles directs et alias en lecture seule {#aliases}&quot;">​</a></h2><p>Les dates et horodatages reçoivent directement le rôle <code>date</code>. Le texte enregistré et les droits d’écriture sont conservés ; dans HA, <code>uptime</code> désigne la date de démarrage, pas une durée écoulée.</p><p>Dans ioBroker, les rôles de mesure et de capteur binaire sont en lecture seule. Si la source MQTT l’est déjà, seul son rôle générique est remplacé. Si elle est accessible en écriture, un alias en lecture seule est créé sous <code>alias.0.ugso_mqtt_roles</code> ; le rôle et les droits de l’original MQTT restent inchangés. Utilisez l’alias pour les visualisations et analyses. Ses valeurs proviennent toujours de l’état MQTT d’origine.</p><p>Le script vérifie les métadonnées et le type réel de la valeur. Il ne déduit pas les types des noms d’appareils ou des textes <code>on</code>/<code>off</code>. Les métadonnées absentes, unités incompatibles, dates invalides et classes inconnues sont ignorées. Il n’effectue aucune conversion et n’envoie aucune commande. Transmettez <code>device_class</code> et, pour les mesures, l’unité ; sélectionnez aussi ces attributs disponibles en mode manuel. La sélection par étiquette transmet automatiquement les métadonnées standard disponibles.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Classe HA</th><th>Rôle ioBroker</th><th>Vérification</th></tr></thead><tbody><tr><td><code>date</code></td><td><code>date</code></td><td>Date <code>YYYY-MM-DD</code> valide</td></tr><tr><td><code>timestamp</code>, <code>uptime</code></td><td><code>date</code></td><td>Horodatage ISO avec fuseau horaire</td></tr></tbody></table></div><h2 id="numeric" tabindex="-1">Correspondances numériques appliquées <a class="header-anchor" href="#numeric" aria-label="Permalink to &quot;Correspondances numériques appliquées {#numeric}&quot;">​</a></h2><p>Le tableau indique les unités réellement acceptées. Les autres unités restent inchangées et sont ignorées ; les mA ou mV, par exemple, ne sont pas convertis implicitement.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Classe HA</th><th>Rôle ioBroker</th><th>Unités acceptées</th></tr></thead><tbody><tr><td><code>temperature</code></td><td><code>value.temperature</code></td><td><code>°C</code>, <code>°F</code>, <code>K</code></td></tr><tr><td><code>humidity</code></td><td><code>value.humidity</code></td><td><code>%</code></td></tr><tr><td><code>absolute_humidity</code></td><td><code>value.humidity.absolute</code></td><td><code>g/m³</code>, <code>mg/m³</code></td></tr><tr><td><code>battery</code></td><td><code>value.battery</code></td><td><code>%</code></td></tr><tr><td><code>voltage</code></td><td><code>value.voltage</code></td><td><code>V</code></td></tr><tr><td><code>current</code></td><td><code>value.current</code></td><td><code>A</code></td></tr><tr><td><code>power</code></td><td><code>value.power</code></td><td><code>W</code>, <code>kW</code></td></tr><tr><td><code>energy</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>energy_storage</code></td><td><code>value.energy</code></td><td><code>Wh</code>, <code>kWh</code></td></tr><tr><td><code>reactive_power</code></td><td><code>value.power.reactive</code></td><td><code>var</code>, <code>kvar</code>, <code>kVar</code></td></tr><tr><td><code>reactive_energy</code></td><td><code>value.energy.reactive</code></td><td><code>varh</code>, <code>kvarh</code>, <code>kVarh</code></td></tr><tr><td><code>frequency</code></td><td><code>value.frequency</code></td><td><code>Hz</code></td></tr><tr><td><code>pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>atmospheric_pressure</code></td><td><code>value.pressure</code></td><td><code>hPa</code>, <code>mbar</code></td></tr><tr><td><code>illuminance</code></td><td><code>value.brightness</code></td><td><code>lx</code>, <code>lux</code></td></tr><tr><td><code>distance</code></td><td><code>value.distance</code></td><td><code>m</code>, <code>km</code>, <code>cm</code>, <code>mm</code>, <code>mi</code>, <code>nmi</code>, <code>yd</code>, <code>ft</code>, <code>in</code></td></tr><tr><td><code>duration</code></td><td><code>value.interval</code></td><td><code>s</code>, <code>ms</code>, <code>h</code>, <code>d</code></td></tr><tr><td><code>wind_speed</code></td><td><code>value.speed</code></td><td><code>m/s</code>, <code>km/h</code>, <code>mph</code>, <code>kn</code></td></tr><tr><td><code>volume_flow_rate</code></td><td><code>value.flow</code></td><td><code>m³/h</code></td></tr><tr><td><code>signal_strength</code></td><td><code>value.rssi</code></td><td><code>dBm</code></td></tr><tr><td><code>aqi</code></td><td><code>value.airquality</code></td><td>—</td></tr><tr><td><code>carbon_dioxide</code></td><td><code>value.co2</code></td><td><code>ppm</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>value.co</code></td><td><code>ppm</code></td></tr><tr><td><code>nitrogen_monoxide</code></td><td><code>value.no</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>nitrogen_dioxide</code></td><td><code>value.no2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>ozone</code></td><td><code>value.o3</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>sulphur_dioxide</code></td><td><code>value.so2</code></td><td><code>ppm</code>, <code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm1</code></td><td><code>value.pm1</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm25</code></td><td><code>value.pm25</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>pm10</code></td><td><code>value.pm10</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>radon</code></td><td><code>value.rn</code></td><td><code>Bq/m³</code></td></tr><tr><td><code>volatile_organic_compounds</code></td><td><code>value.tvoc</code></td><td><code>µg/m³</code>, <code>μg/m³</code></td></tr><tr><td><code>volatile_organic_compounds_parts</code></td><td><code>value.tvoc</code></td><td><code>ppb</code></td></tr></tbody></table></div><h2 id="binary" tabindex="-1">Capteurs binaires <a class="header-anchor" href="#binary" aria-label="Permalink to &quot;Capteurs binaires {#binary}&quot;">​</a></h2><p>Seules les véritables valeurs booléennes avec un type d’objet compatible sont acceptées. Les textes HA habituels <code>on</code> et <code>off</code> restent inchangés et ne reçoivent pas de rôle booléen. Pour <code>battery</code>, vrai signifie batterie faible ; pour <code>lock</code>, vrai signifie déverrouillé.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Classe HA</th><th>Rôle ioBroker</th></tr></thead><tbody><tr><td><code>battery</code></td><td><code>indicator.lowbat</code></td></tr><tr><td><code>connectivity</code></td><td><code>indicator.reachable</code></td></tr><tr><td><code>door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>garage_door</code></td><td><code>sensor.door</code></td></tr><tr><td><code>window</code></td><td><code>sensor.window</code></td></tr><tr><td><code>opening</code></td><td><code>sensor.contact</code></td></tr><tr><td><code>lock</code></td><td><code>sensor.lock</code></td></tr><tr><td><code>motion</code></td><td><code>sensor.motion</code></td></tr><tr><td><code>moisture</code></td><td><code>sensor.alarm.flood</code></td></tr><tr><td><code>smoke</code></td><td><code>sensor.alarm.fire</code></td></tr><tr><td><code>carbon_monoxide</code></td><td><code>sensor.alarm.co</code></td></tr><tr><td><code>light</code></td><td><code>sensor.light</code></td></tr><tr><td><code>sound</code></td><td><code>sensor.noise</code></td></tr><tr><td><code>problem</code></td><td><code>indicator.error</code></td></tr><tr><td><code>running</code></td><td><code>indicator.working</code></td></tr></tbody></table></div><h2 id="conditional" tabindex="-1">Autres correspondances examinées <a class="header-anchor" href="#conditional" aria-label="Permalink to &quot;Autres correspondances examinées {#conditional}&quot;">​</a></h2><p>Le mode rôles seul n’applique pas ces cas automatiquement. Le mode virtuel réalise désormais les fonctions Light et interrupteur ci-dessous avec les vérifications indiquées ; les niveaux, consommation/production et classes ambiguës ne sont toujours pas devinés.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Classe/fonction HA</th><th>Rôle possible</th><th>Condition supplémentaire</th></tr></thead><tbody><tr><td><code>volume_storage</code></td><td><code>value.fill</code></td><td>Confirmer un niveau réel de réservoir</td></tr><tr><td><code>water</code>, <code>gas</code></td><td>Mesure générique</td><td>Une consommation n’est pas un niveau</td></tr><tr><td><code>energy</code></td><td><code>value.energy.consumed</code> / <code>value.energy.produced</code></td><td>Identifier explicitement consommation ou production</td></tr><tr><td><code>speed</code></td><td><code>value.speed</code></td><td>Ne pas supposer qu’il s’agit du vent</td></tr><tr><td><code>moisture</code> numérique</td><td>Mesure générique</td><td>Distinguer d’une alarme d’eau binaire</td></tr><tr><td>Retour de luminosité</td><td><code>value.dimmer</code></td><td>Confirmer le pourcentage et la fonction Light</td></tr><tr><td>Commande de luminosité</td><td><code>level.dimmer</code></td><td>Raccorder correctement un canal de commande séparé</td></tr><tr><td>Retour d’interrupteur</td><td><code>sensor.switch</code></td><td>Normaliser une valeur booléenne</td></tr><tr><td>Commande d’interrupteur</td><td><code>switch</code> / <code>switch.light</code></td><td>Raccorder <code>/set</code> ; aucune commande à l’installation</td></tr><tr><td>Commande de température de couleur</td><td><code>level.color.temperature</code></td><td>Kelvin, limites et canal de commande</td></tr><tr><td>Sélection d’effet</td><td><code>level.effect</code></td><td>Liste d’effets et canal de commande</td></tr><tr><td>Commande RGB</td><td><code>level.color.rgb</code></td><td>Convertir le tableau JSON en couleur hexadécimale</td></tr></tbody></table></div><p>Aucun rôle spécifique n’est deviné pour <code>occupancy</code>, <code>presence</code>, <code>moving</code>, <code>plug</code>, <code>power</code> binaire, <code>battery_charging</code>, <code>cold</code>, <code>heat</code>, <code>gas</code> binaire, <code>glass_break</code>, <code>safety</code>, <code>tamper</code>, <code>update</code> ou <code>vibration</code>. Des rôles génériques <code>sensor</code>/<code>indicator</code> ou règles personnalisées sont possibles mais exclus de cette attribution automatique prudente. Toutes les autres classes non indiquées restent également inchangées.</p><h2 id="restore" tabindex="-1">Restauration <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Restauration {#restore}&quot;">​</a></h2><p>Arrêtez le script, choisissez <code>mode: &#39;restore&#39;</code>, puis relancez-le. Seules ses propres modifications de rôle sont restaurées, si le rôle et le type actuels correspondent encore à l’entrée sauvegardée. Les modifications manuelles ultérieures sont conservées. Ses alias non modifiés sont supprimés ; les alias modifiés ou étrangers sont conservés. Les valeurs MQTT d’origine ne sont jamais supprimées.</p><p>Arrêtez ensuite le script. Conservez le journal et les exclusions. Les points déjà enregistrés ne sont pas traités de nouveau avec le même journal ; une nouvelle opération exige un nouveau <code>backupId</code> choisi délibérément et, pour les alias, un <code>aliasRoot</code> libre.</p><p>Vérification locale avec des API ioBroker simulées : aperçu, échecs de sauvegarde, types, unités, modifications manuelles, alias et restauration. Pas encore testé dans une installation ioBroker réelle.</p><p><a href="https://www.home-assistant.io/integrations/sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Sensor</a> · <a href="https://www.home-assistant.io/integrations/binary_sensor/#device-class" target="_blank" rel="noreferrer">Home Assistant: Binary sensor</a> · <a href="https://www.iobroker.com/docs/dev/stateroles.md" target="_blank" rel="noreferrer">ioBroker: State roles</a> · <a href="https://github.com/ioBroker/ioBroker.javascript/blob/v10.4.10/docs/en/javascript.md" target="_blank" rel="noreferrer">ioBroker: JavaScript API</a></p>`,77)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
